package app.morphe.extension.tiktok.settings;

import java.util.Map;

/**
 * The settings text in every language the bundle carries.
 *
 * Generated by scripts/gen-l10n.py from extensions/tiktok/src/main/l10n. Do not edit by
 * hand: edit the table under src/main/l10n and run the script.
 *
 * The translations live here rather than in TikTok's resources because merging them into
 * a resource table of 74,765 strings costs more patching memory than Morphe Manager gives
 * by default. Each language's table is its own generated class beside this one, since one
 * file holding all of them grew past the 2,500 KB Android Lint reads.
 */
public final class L10nTranslations {
    private L10nTranslations() {
    }

    /** The language tags with a table, lower case, in the order they are tried. */
    static final String[] LANGUAGES = {"az", "de", "es", "in", "it", "pt-rbr", "ru", "tr", "zh-hans"};

    /**
     * The table for one language tag, or null when nothing was translated into it.
     * A language with two ISO codes answers to both, because Android reports the
     * legacy one and a desktop JVM reports the new one.
     */
    static Map<String, String> of(String language) {
        switch (language) {
            case "az":
                return L10nTranslationsAz.build();
            case "de":
                return L10nTranslationsDe.build();
            case "es":
                return L10nTranslationsEs.build();
            case "in":
            case "id":
                return L10nTranslationsIn.build();
            case "it":
                return L10nTranslationsIt.build();
            case "pt-rbr":
                return L10nTranslationsPt_rBR.build();
            case "ru":
                return L10nTranslationsRu.build();
            case "tr":
                return L10nTranslationsTr.build();
            case "zh-hans":
                return L10nTranslationsZh_Hans.build();
            default:
                return null;
        }
    }
}
